    E.EMPRESA_ID,
    E.RAZAO_SOCIAL,
    F.CADASTRO_ID,
    C.RAZAO_SOCIAL AS CLIENTE,
    F.FINANCEIRO_ID AS TITULO,
    F.DT_EMISSAO,
    F.DT_VENCTO,
    MAX(FB.DT_PAGAMENTO) AS DT_PAGAMENTO, 
    F.VL_TITULO,
    CAST(F.VL_TITULO - ISNULL(F.VL_DESCONTO, 0) AS DECIMAL(18,2)) AS VL_TOTAL,
    SUM(FB.VL_PAGO) AS VL_PAGO,
    CAST(
        (F.VL_TITULO - ISNULL(F.VL_DESCONTO, 0)) 
        - SUM(FB.VL_PAGO)
    AS DECIMAL(18,2)) AS SALDO,
    FB.SALDO_RESTANTE,
    F.VL_DESCONTO,
    F.DIAS_ATRASO,
    F.PORTADOR_ID,
    P.NOME AS PORTADOR,
    F.SITUACAO

FROM FINANCEIRO F

INNER JOIN FINANCEIRO_BAIXA FB
    ON FB.FINANCEIRO_ID = F.FINANCEIRO_ID
    AND FB.EMPRESA_ID = F.EMPRESA_ID
    AND FB.VL_PAGO > 0 

INNER JOIN EMPRESA E 
    ON E.EMPRESA_ID = F.EMPRESA_ID 

INNER JOIN CADASTRO C 
    ON C.CADASTRO_ID = F.CADASTRO_ID 

LEFT JOIN PORTADOR P 
    ON P.PORTADOR_ID = F.PORTADOR_ID

WHERE 
    F.TP_CONTA = ''R''

    AND (
        F.STATUS = ''B'' 
        OR (F.STATUS = ''A'' AND F.SITUACAO = ''PAGTO PARCIAL'') 
        OR (F.STATUS = ''A'' AND F.SITUACAO = ''VENCIDO'')
    )

    AND $X{IN, E.EMPRESA_ID, EMPRESA}
    AND ($P{DTINICIO} IS NULL OR FB.DT_PAGAMENTO >= $P{DTINICIO})
    AND ($P{DTFINAL} IS NULL OR FB.DT_PAGAMENTO <= $P{DTFINAL})
    AND ($P{CLIENTEFORNECEDOR} IS NULL OR C.CADASTRO_ID = $P{CLIENTEFORNECEDOR})

GROUP BY
    E.EMPRESA_ID,
    E.RAZAO_SOCIAL,

    F.CADASTRO_ID,
    C.RAZAO_SOCIAL,
    F.FINANCEIRO_ID,
    FB.SALDO_RESTANTE,
    F.DT_EMISSAO,
    F.DT_VENCTO,
    F.VL_TITULO,
    F.VL_DESCONTO,
    F.DIAS_ATRASO,
    F.PORTADOR_ID,
    P.NOME,
    F.SITUACAO

ORDER BY 
    C.RAZAO_SOCIAL,
    F.DT_EMISSAO', NULL, NULL, true, '2026-05-08 17:51:29.388002+00', '2026-05-08 17:51:45.403414+00', '');
  e.razao_social,
  e.logomarca,
  c.cadastro_id,
  c.razao_social AS nome_cliente,
  f.financeiro_id AS titulo,
  f.documento,
  f.vl_titulo,
  f.vl_pago,
  f.vl_juros,
  f.vl_desconto,
  f.vl_a_pagar AS saldo,
  (f.vl_titulo - COALESCE(f.vl_desconto, 0))::DECIMAL(18,2) AS vl_total,
  f.dt_emissao,
  f.dt_vencto,
  f.dias_atraso,
  f.situacao,
  f.tp_conta,
  c.fone_geral
FROM financeiro_view f
JOIN empresa e ON f.empresa_id = e.empresa_id
JOIN cadastro c ON c.cadastro_id = f.cadastro_id
LEFT JOIN financeiro_baixa fb ON fb.financeiro_id = f.financeiro_id AND fb.empresa_id = f.empresa_id
WHERE f.status = ''A'' 
  AND f.tp_conta = ''R''
  AND ({{empresa_id}} IS NULL OR e.empresa_id = {{empresa_id}})
  AND ({{dt_inicial}} IS NULL OR f.dt_emissao >= {{dt_inicial}}::DATE)
  AND ({{dt_final}} IS NULL OR f.dt_emissao < ({{dt_final}}::DATE + INTERVAL ''1 day''))
  AND ({{cadastro_id}} IS NULL OR c.cadastro_id = {{cadastro_id}})
ORDER BY
  f.dt_emissao,
  c.razao_social', NULL, '{"bands": {"detail": {"height": 5, "bgColor": "transparent", "visible": true, "components": [{"h": 5, "w": 15, "x": 1, "y": 0, "id": "821k7a6q", "type": "text", "style": {"bold": false, "align": "left", "color": "#1a1a1a", "border": "none", "italic": false, "bgColor": "transparent", "padding": 2, "fontSize": 8, "underline": false, "borderColor": "#cccccc"}, "content": "{documento}"}, {"h": 5, "w": 65, "x": 17, "y": 0, "id": "393p5zuo", "type": "text", "style": {"bold": false, "align": "left", "color": "#1a1a1a", "border": "none", "italic": false, "bgColor": "transparent", "padding": 2, "fontSize": 8, "underline": false, "borderColor": "#cccccc"}, "content": "{nome_cliente}"}, {"h": 5, "w": 20, "x": 103, "y": 0, "id": "0ucth8co", "type": "text", "style": {"bold": false, "align": "center", "color": "#1a1a1a", "border": "none", "italic": false, "bgColor": "transparent", "padding": 2, "fontSize": 8, "underline": false, "borderColor": "#cccccc"}, "format": "date", "content": "{dt_vencto}"}, {"h": 5, "w": 20, "x": 234, "y": 0, "id": "nm4razmi", "type": "text", "style": {"bold": false, "align": "right", "color": "#1a1a1a", "border": "none", "italic": false, "bgColor": "transparent", "padding": 2, "fontSize": 8, "underline": false, "borderColor": "#cccccc"}, "format": "number", "content": "{vl_pago}", "decimals": 2}, {"h": 5, "w": 30, "x": 337.7, "y": 0, "id": "y8pb4zdk", "type": "text", "style": {"bold": false, "align": "center", "color": "#1a1a1a", "border": "none", "italic": false, "bgColor": "transparent", "padding": 2, "fontSize": 9, "underline": false, "borderColor": "#cccccc"}, "content": "Texto"}, {"h": 5, "w": 20, "x": 83, "y": 0, "id": "wtnoots6", "type": "text", "style": {"bold": false, "align": "center", "color": "#1a1a1a", "border": "none", "italic": false, "bgColor": "transparent", "padding": 2, "fontSize": 8, "underline": false, "borderColor": "#cccccc"}, "format": "date", "content": "{dt_emissao}"}, {"h": 5, "w": 20, "x": 133, "y": 