  e.razao_social,
  e.logomarca,
  c.cadastro_id,
  c.razao_social AS nome_cliente,
  f.financeiro_id AS titulo,
  f.documento,
  f.vl_titulo,
  f.vl_pago,
  f.vl_juros,
  f.vl_desconto,
  f.vl_a_pagar AS saldo,
  (f.vl_titulo - COALESCE(f.vl_desconto, 0))::DECIMAL(18,2) AS vl_total,
  f.dt_emissao,
  f.dt_vencto,
  f.dias_atraso,
  f.situacao,
  f.tp_conta,
  c.fone_geral
FROM financeiro_view f
JOIN empresa e ON f.empresa_id = e.empresa_id
JOIN cadastro c ON c.cadastro_id = f.cadastro_id
LEFT JOIN financeiro_baixa fb ON fb.financeiro_id = f.financeiro_id AND fb.empresa_id = f.empresa_id
WHERE f.status = ''A'' 
  AND f.tp_conta = ''P''
  AND ({{empresa_id}} IS NULL OR e.empresa_id = {{empresa_id}})
  AND ({{dt_inicial}} IS NULL OR f.dt_emissao >= {{dt_inicial}}::DATE)
  AND ({{dt_final}} IS NULL OR f.dt_emissao < ({{dt_final}}::DATE + INTERVAL ''1 day''))
  AND ({{cadastro_id}} IS NULL OR c.cadastro_id = {{cadastro_id}})
ORDER BY
